bool ARMJIT_Memory::IsFastMemSupported()
{
#ifdef KOKI_NDS_BOUNDED_MEMORY
    PageSize = sysconf(_SC_PAGESIZE);
    PageShift = __builtin_ctz(PageSize);
    return false;
#endif

    ARMJIT_Global::Init();
#ifdef KOKI_NDS_BOUNDED_MEMORY
    // Koki uses the JIT slow-memory path. No mirrored 8 GB address space,
    // shared-memory descriptor or signal handler is needed for this path.
    PageSize = sysconf(_SC_PAGESIZE);
    PageShift = __builtin_ctz(PageSize);
    MemoryBase = static_cast<u8*>(mmap(nullptr, MemoryTotalSize,
        PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0));
    if (MemoryBase == MAP_FAILED) { MemoryBase = nullptr; throw std::bad_alloc(); }
    FastMem9Start = nullptr;
    FastMem7Start = nullptr;
    return;
#endif
#if defined(__SWITCH__)

ARMJIT_Memory::~ARMJIT_Memory() noexcept
{
#ifdef KOKI_NDS_BOUNDED_MEMORY
    if (MemoryBase) munmap(MemoryBase, MemoryTotalSize);
    MemoryBase = nullptr;
    ARMJIT_Global::DeInit();
    return;
#endif
